package net.civeira.phylax.feature.observe.observedsource.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class OriginRefVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property origin ref of observed source ")
  void test_origin_ref_v_o_builder() {
    Assertions.assertFalse(OriginRefVO.nullValue().getOriginRef().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(OriginRefVO.tryFrom(null).getOriginRef().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one", OriginRefVO.from("one").getOriginRef().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> OriginRefVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", OriginRefVO.from("one").toString());
  }
}
